# -*- coding: utf-8 -*-
"""第65批 t1359 佛说花积楼阁陀罗尼经 白话译文（section + modern）。original_preview 由骨架提供；咒文照录原文用字。"""

INTRO = {
 "t1359": '《佛说花积楼阁陀罗尼经》为宋代译经三藏施护所译，属密教陀罗尼经。经以师子游戏菩萨启问「如来福蕴当云何得？又于如来作供养者，云何因果无量无边」为缘起：佛答如来具足戒、定、慧、解脱、解脱知见五法故福蕴无量，供养如来当得涅槃，乃至舍利供养、塔所供养（一花一灯、扫拂洒净）能灭先世应堕地狱之罪；末说此陀罗尼乃十方无量无边诸佛同共宣说，受持读诵、为人演说者永不堕恶趣、得宿命通与辩才，并明持咒仪轨（白月八日起首、六时念诵、至十五日得见佛），可供人受持此陀罗尼、依仪修行之用。',
}

T1359 = [
 ('译者·缘起·师子游戏启问',
  '【译者·缘起·师子游戏启问】本经由西天译经三藏、朝散大夫、试鸿胪少卿、传法大师施护奉诏翻译。我这样听闻：有一次，世尊在阿耨达池无热恼龙王宫，与大比丘众四百五十人在一起。又有师子游戏菩萨等大菩萨众，具足千人，一切皆得陀罗尼、十地圆满，得灌顶已、位居补处，披大甲胄、趣向诸佛之德，心不退转、名称普闻。【义解】本段是全经开端：先标译者施护；次述佛在阿耨达池无热恼龙王宫与四百五十位大比丘共会，另有师子游戏等千位大菩萨在座——皆得陀罗尼、十地圆满、位居补处、心不退转。此铺陈法会之盛，为下段师子游戏菩萨启问作引。'),
 ('师子游戏启问',
  '【师子游戏启问】如此等大菩萨，都从他方而来集会。那时，师子游戏大菩萨从座而起，偏袒右肩，来到世尊之前，右膝著地、合掌恭敬而禀白佛说：「世尊！如来的福蕴应当怎样获得？又对如来作供养的人，因果为何无量无边？唯愿如来慈悲开示。【义解】本段写成问的启请：师子游戏菩萨从座而起、偏袒右肩、右膝著地、合掌恭肃，请问二义——如来福蕴云何而得、对如来作供养者云何因果无量无边。此二问即全经的纲要，下段即佛的答说。'),
 ('佛赞许·如来五法',
  '【佛赞许·如来五法】」作此说后，凝心而住。那时，佛告诉师子游戏大菩萨说：「善哉善哉！善男子！你今问我『如来福蕴云何而得？又对如来作供养者，云何因果无量无边？』你当仔细听，我今为你说。」佛说：「善男子！如来有五法，具足功德无量无边。【义解】本段佛先赞许师子游戏之问，敕其谛听，随即标出「如来有五法，具足功德无量无边」的总纲。下段即列此五法之名（戒、定、慧、解脱、解脱知见），并说供养如来所得之果。'),
 ('五法·供养得涅槃',
  '【五法·供养得涅槃】什么是五法？就是戒、定、慧、解脱、解脱知见。善男子！如来具足如此五法的无量功德，所以获得福蕴无量无边。善男子！若对如来作供养的人，当得涅槃。若那三乘之人，随其发心，各各所见而得涅槃。善男子！若见如来、应正等觉，以清净心谛信归命、尊重称赞，又以衣服、卧具、病缘医药及一切所须而供养的，所获果报无量无边。【义解】本段列出如来五法——戒、定、慧、解脱、解脱知见，并明如来具此五法故福蕴无量；随即说供养如来之果：能得涅槃，三乘之人随其发心各见涅槃；若以清净心归命称赞、以衣服卧具医药等四事供养者，果报无量无边。'),
 ('舍利供养最上·菩提心施最胜',
  '【舍利供养最上·菩提心施最胜】善男子！又若如来般涅槃后，有人获得如来的舍利如芥子许而供养的，所获果报在一切供养中最为殊胜。又，作种种福，若对如来舍利作供养的，其福最上。师子游戏！若又有人持如妙高山等量的宝聚，布施供养声闻及辟支佛，所获果报，不如在家及出家菩萨发无上正等觉心、以一金钱布施供养如来应正等觉。【义解】本段以校量显胜：供养如来舍利（乃至芥子许）之福最为殊胜；然以妙高山等宝聚布施声闻、辟支佛之福，不及发菩提心的在家出家菩萨以一金钱供养如来。此特赞「发菩提心而供佛」之福，远超二乘之施。'),
 ('发心供佛之福·建塔供舍利',
  '【发心供佛之福·建塔供舍利】以先前方便的善根对比后来方便的善根，百分不及一、千分不及一、百千分不及一，乃至算分、数分、譬喻分、譬喻转分，乃至算数譬喻所不能及。善男子！又，如来住世百年、千年乃至百千年，应化之缘已毕而般涅槃后，以佛舍利而起妙塔。【义解】本段承上以数目校量发心供佛之福——非算数譬喻所能及；随即转入「舍利塔供养」：如来住世百余千年、应化毕已入涅槃后，以佛舍利起妙塔。此下即说于塔所供养之福与灭罪之功。'),
 ('塔所供养·灭罪之福',
  '【塔所供养·灭罪之福】若又有人在此塔所，以香泥涂地作曼拏罗（坛场），施设花鬘、涂香、烧香、燃灯、志心供养，乃至持一花一灯以为供养，或持帚拂除去尘坌，或以一掬水用作洒净，如此之人因志心的缘故获福无量。此人先世所有的罪业本应堕阿鼻地狱，因于塔所作供养的缘故，先世的罪报都得以除灭。【义解】本段说于舍利塔所作供养的功德：以香泥涂地作坛、设花鬘涂香烧香燃灯、乃至一花一灯、扫拂除尘、一掬水洒净，因志心而得无量之福；更明此人先世应堕阿鼻地狱的罪业，因塔所供养而悉得除灭。此显塔供之灭罪力用。'),
 ('一念归命佛·不堕恶趣',
  '【一念归命佛·不堕恶趣】善男子！若又有人发一念心归命于佛，又不中途退转、又不轻慢，此人在将来百劫、千劫乃至百千劫中常感殊胜之福，生于人天，不再堕落一切恶趣。善男子！我今宣说此花积楼阁陀罗尼经，正是为了利益安乐天上人间一切众生的缘故。【义解】本段说「一念归命佛」之福：发一念归命佛心而中不退转、不轻慢者，于百千劫中常感胜福、生人天、不堕恶趣；末佛自陈宣说此《花积楼阁陀罗尼经》的用意——为利益安乐天上人间一切众生。此下即明受持此经之功德，并说陀罗尼。'),
 ('受持此经之功德',
  '【受持此经之功德】善男子！若又有人得此花积楼阁陀罗尼经，志心受持读诵供养，又演绎其中真实的义趣、广为人说，此人永不堕一切恶趣，也不生于卑下种族，常生人天殊胜之处，诸根圆满、获得宿命通，具足种种甚深辩才，恒常得遇佛法僧宝，又得如来忆念覆护，得菩提心永不退转。【义解】本段说受持此经的功德：志心受持、读诵、供养、演其义趣、广为人说者，永离恶趣、不生卑贱、常生人天、诸根圆满、得宿命通与深妙辩才、恒遇三宝、蒙佛忆护、菩提心不退。此极赞受持此经之利，下段即正式宣说陀罗尼。'),
 ('陀罗尼咒文（一）',
  '【陀罗尼咒文（一）】」\n爾時世尊即說陀羅尼曰：\n「怛儞也（二合）他（引）（一）\u3000馱囉尼馱囉尼（二）\u3000母儞（引）鉢囉（二合）婆（引）娑嚩（二合）哩（引）（三）\u3000悉地（引）贊捺哩（二合引）（四）曩（引）他唧儞哩賀（二合引）【义解】本段为陀罗尼咒文，照录原文用字（含（二合）（引）等音注括注），不译其义，唯依原文分段；此为十方无量无边诸佛如来同共宣说之陀罗尼。'),
 ('陀罗尼咒文（二）',
  '【陀罗尼咒文（二）】哩（引）（五）\u3000阿（引）嚕（引）誐也（二合）嚩底（六）\u3000沒馱縛底（七）\u3000尾哩（引）烏迦致囉祖波誐帝（引）（八）\u3000帝（引）祖嚩底（九）\u3000尾捨（引）羅沒地達哩麼（二合引）嚩婆（引）細（引）（十）【义解】本段为陀罗尼咒文，照录原文用字（含（二合）（引）等音注括注），不译其义，唯依原文分段；此为十方无量无边诸佛如来同共宣说之陀罗尼。'),
 ('陀罗尼咒文（三）',
  '【陀罗尼咒文（三）】阿乞叉（二合）野羯臘閉（二合引）（十一）\u3000羯臘波（二合）嚩底（十二）\u3000阿蜜哩（二合）哆羯臘閉（二合引）（十三）護哆（引）舍儞（引）（十四）\u3000帝（引）祖嚩底儞怛也（二合）三摩（引）呬帝（引）【义解】本段为陀罗尼咒文，照录原文用字（含（二合）（引）等音注括注），不译其义，唯依原文分段；此为十方无量无边诸佛如来同共宣说之陀罗尼。'),
 ('陀罗尼咒文（四）',
  '【陀罗尼咒文（四）】（十五）\u3000帝（引）祖嚩底底乞叉𧹞（三合）捺哩（二合）野沒地娑嚩（二合引）賀（引）（十六）」\n「善男子！此陀羅尼乃是十方無量無邊諸佛如來同共宣說。若復有人聞此陀羅尼經名字，發至誠心恭信供養，是人當來獲得無量無邊功德。【义解】本段为陀罗尼咒文，照录原文用字（含（二合）（引）等音注括注），不译其义，唯依原文分段；此为十方无量无边诸佛如来同共宣说之陀罗尼。'),
 ('持咒仪轨·见佛得定',
  '【持咒仪轨·见佛得定】又，若有人持此陀罗尼，先修成前行之后，于二月、三月或八月，取白月八日起首，发至诚心，在一昼夜中六时念此陀罗尼并忆念诸佛如来，心不散乱。又以涂香、妙花、烧香、燃灯种种供养，心不间断。至十五日，决定能得见世尊坐莲华藏座宣说陀罗尼法。【义解】本段说持咒的仪轨与所求之验：持此陀罗尼、先行成就后，于白月八日起首（二月、三月或八月择一），一昼夜六时念咒念佛、心不散乱，并以涂香、妙花、烧香、燃灯种种供养不间断，至十五日决定得见世尊坐莲华藏座说陀罗尼法。此明持咒得见佛的修法。'),
 ('持诵得益·结经',
  '【持诵得益·结经】持诵之人应时获得意愿圆满，心垢尽除、证得宿命通，得诸禅定、安住四圣谛，解诸法义论及工巧事业，乃至临命终时耳根不坏，都能了别一切胜事，乃至或闻如来为说四圣谛等无漏之法。」那时，世尊说完此陀罗尼经，师子游戏大菩萨，以及诸大菩萨、大比丘众、天、人、阿修罗、乾闼婆等，闻佛所说，皆大欢喜，礼佛而退。【义解】本段以持诵之益作结：持诵者应时意愿圆满、心垢尽除、证宿命通、得禅定、住四圣谛、解诸法义与工巧，临终身根不坏、了别胜事乃至闻佛说四圣谛等法；随即结集全经——师子游戏等菩萨、比丘、天人阿修罗乾闼婆众闻法欢喜、礼佛而退。'),
]
